window.ObservationContent={
 evidence:[
 {title:'星系群与团',section:'2.5 · pp.67–72',measurement:'成员的天球位置、红移与速度分布；热气体的 X 射线；背景星系的透镜形变。',inference:'用不同探针估计引力质量与物质分布，并检验星系所处的环境。',caveat:'天球上的密集不一定意味着真实成员关系。动力学和气体方法需要考虑平衡假设，透镜还依赖投影与几何。',paragraphs:['群和团把星系集中在共同的引力环境中。成员数、空间集中程度与速度信息共同帮助识别系统；单凭一张二维图像，前景和背景对象可能混入其中。','成员运动、热气体的 X 射线和引力透镜提供互补的质量信息。它们对平衡状态、气体物理和投影的依赖不同；多种方法相互比较，比单一指标更有说服力。']},
 {title:'高红移星系',section:'2.6 · pp.72–81',measurement:'多波段通量、谱线、连续谱突变和不同深度下的星系计数。',inference:'估计红移，构建特定族群的样本，再推断光度函数和宇宙恒星形成率随时间的变化。',caveat:'测光红移可能有简并；紫外选择容易漏掉尘埃遮蔽的系统。观测波段对应的静止系波段也会随红移变化。',paragraphs:['同一个滤光片在不同红移下看到的是不同的静止系波段。比较远近星系时，要处理这种波段变化，以及距离、面亮度变暗和样本选择。不能把本章开头的欧氏距离实验直接搬到高红移。','测光红移使用多波段对光谱形状的粗采样；Lyman-break 方法利用谱中的突变选取候选体；窄带成像寻找特定红移范围内的强线；亚毫米观测补充尘埃遮蔽的恒星形成系统。这些方法得到的样本彼此补充，并不天然代表所有星系。','宇宙恒星形成史需要把光度函数与光度到形成率的校准结合。尘埃、初始质量函数、漏检与外推都会影响结果；本页重点保留推断链，不重绘一条没有数据来源的“观测曲线”。']},
 {title:'大尺度结构',section:'2.7 · pp.81–85',measurement:'星系在天球和红移空间中的成对分布；背景图像之间微弱但相关的形变。',inference:'量化聚类，并借助弱引力透镜约束沿视线投影的物质分布。',caveat:'星系并非无偏的物质示踪物；本动速度改变红移空间结构。单个椭圆图像也不足以认定引力剪切。',paragraphs:['星系排列成群、团、丝状结构与空洞。两点相关函数比较某一间距的星系对数与随机分布的期望值；比较时需要匹配观测窗口、选择函数和归一化。它是统计描述，不是一张单个星系的形成路线图。','用红移替代距离会混入本动速度，得到的红移空间聚类不同于真实空间聚类。弱透镜通过大量背景图像的相关形变提供另一条质量探针，但必须处理本征形状和仪器形变等因素。']},
 {title:'星系际介质',section:'2.8 · pp.85–89',measurement:'背景类星体连续谱上的吸收线、吸收边和大范围的通量减弱。',inference:'约束视线上的中性氢柱密度、化学成分和电离状态。',caveat:'吸收饱和后，几乎零通量并不能唯一确定中性比例。还要知道辐射场和电离修正，才能从中性氢推断总气体。',paragraphs:['稀薄气体自身可能很难发光，却能在背景光源的光谱中留下吸收。Lyα 森林、Lyman-limit 系统和阻尼 Lyα 系统，强调了不同柱密度与吸收特征；金属线则补充化学信息。','Gunn–Peterson 检验利用中性氢对 Lyα 的强吸收。没有明显吸收与出现饱和吸收，提供的是不同形式的约束；“暗下去多少”与“有多少中性物质”之间并非在所有范围都存在简单的一一映射。']},
 {title:'宇宙微波背景',section:'2.9 · pp.89–92',measurement:'接近黑体的背景谱，以及扣除运动偶极和前景后残留的微小温度各向异性。',inference:'约束早期宇宙的热历史、原初扰动和宇宙学模型参数。',caveat:'平均温度、运动偶极、银河系前景和宇宙学起伏必须区分。参数约束依赖模型与数据处理。',paragraphs:['微波背景把星系问题连接到早期热宇宙：近黑体谱与近各向同性是整体证据，小幅温度起伏则包含初始扰动的信息。两者是不同层次的观测。','温度图不能把每一个亮暗斑都直接读作今日的一座星系。通过角功率谱比较不同角尺度，再结合其他观测，才能检验宇宙成分、几何与扰动模型。教材中的 COBE 与 WMAP 结果在此作为历史证据讨论。']},
 {title:'宇宙学背景与成分',section:'2.10 · pp.92–99',measurement:'距离与红移的关系、背景辐射、元素丰度，以及不同尺度的引力质量证据。',inference:'在指定的宇宙学模型中，联合约束膨胀史和物质、辐射、暗能量等成分。',caveat:'光度距离与角直径距离承担不同角色；参数可能相互简并。无法直接用某个星系的质量光度比代表整个宇宙。',paragraphs:['均匀、各向同性描述的是足够大尺度上的宇宙学背景，并不否认局部存在星系和团。红移与尺度因子的联系，为下一章的几何和动力学提供起点。','通量关系使用光度距离，角大小关系使用角直径距离。不同成分随膨胀的变化不同，单一观测常只能限制参数组合，因此需要多种证据联合检验。第 3 章将从尺度因子、距离和 Friedmann 方程建立这一框架。']}
 ],
 quizzes:[
 ['同一座已分辨的星系，在本页理想欧氏模型中距离加倍，什么保持不变？',['整座星系的总通量。','半光区平均面亮度。'],1,'总通量与角面积都变为四分之一，平均面亮度不变；角半径减半。宇宙学变暗和仪器效应不在这个模型内。依据 §2.1 pp.26–29。'],
 ['只提高速度弥散，光谱里主要改变什么？',['所有谱线中心一起移向红端。','谱线变宽，中心红移保持不变。'],1,'本实验中红移决定中心，速度分布与仪器响应共同决定线宽。真实光谱还需考虑热展宽和不同成分。依据 §2.1.2 pp.30–32。'],
 ['把 Sérsic 指数从 1 调到 4，在各自的有效半径内有多少总光？',['两者都是 50%。','n=4 一定超过 50%。'],0,'有效半径按半光定义；改变 n 会改变中心和外翼的分配，但 bₙ 随之调整，保证 Rₑ 内恰好一半。依据 pp.42–43。'],
 ['体积限制样本完整，是否意味着包含该体积内所有星系？',['是，包括任意暗的星系。','否，只对规定光度阈值之上的对象成立。'],1,'最远边界处必须仍能检测到阈值光度的对象，较暗对象会被排除。实际巡天还有其他选择限制。依据 §2.4 pp.61–62。']
 ]
};
